import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, smoothstep, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const primitiveResults = [];
  let disposed = false;

  const makeMaterial = (nodeColor, transparent = false) => {
    const material = new MeshBasicNodeMaterial({
      transparent,
      depthWrite: !transparent
    });
    material.colorNode = color(nodeColor);
    return material;
  };

  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropUv = uv();
  backdropMaterial.colorNode = mix(
    color('#0b0b10'),
    color('#16161d'),
    smoothstep(0.05, 0.95, backdropUv.y)
  );

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  backdrop.userData.kriptikOwned = true;
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const surfaceMaterial = makeMaterial('#0b0b10');
  const surface = new Mesh(new PlaneGeometry(3.65, 2.35), surfaceMaterial);
  surface.position.set(0, 0, -0.08);
  surface.userData.kriptikOwned = true;
  root.add(surface);
  resources.push(surface.geometry, surface.material);

  const imageMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: true
  });
  const image = new Mesh(new PlaneGeometry(3.5, 2.1875), imageMaterial);
  image.position.set(0, 0, 0.02);
  image.userData.kriptikOwned = true;
  root.add(image);
  resources.push(image.geometry, image.material);

  const accentMaterial = makeMaterial('#ff2a38');
  const accentBars = [
    { x: -1.72, y: 1.08, w: 0.36, h: 0.025 },
    { x: 1.52, y: -1.08, w: 0.56, h: 0.025 },
    { x: -1.74, y: -0.88, w: 0.025, h: 0.28 }
  ];

  for (const bar of accentBars) {
    const accent = new Mesh(
      new BoxGeometry(bar.w, bar.h, 0.025),
      accentMaterial
    );
    accent.position.set(bar.x, bar.y, 0.08);
    accent.userData.kriptikOwned = true;
    root.add(accent);
    resources.push(accent.geometry);
  }
  resources.push(accentMaterial);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      texture.colorSpace = ctx.THREE.SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.colorNode = color('#e8ecf2');
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      result.timeline?.kill?.();
      result.cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.traverse((object) => {
      object.userData = object.userData || {};
    });
  };

  return root;
}
